const raw = $input.first().json || {};
let data = raw;

if (raw.query) {
  if (typeof raw.query === 'string') {
    try { data = JSON.parse(raw.query); } catch (e) { data = raw; }
  } else if (typeof raw.query === 'object') {
    data = raw.query;
  }
}

const bodyContent = data.html || data.body || data.text || '<p>No content</p>';

const template = '<!doctype html>
<html>
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>{{subject}}</title>
  </head>
  <body style="margin:0;padding:0;background:#EEF2F7;color:#111111;font-family:Arial,Helvetica,sans-serif;">
    <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#EEF2F7;padding:24px 0;">
      <tr>
        <td align="center">
          <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="width:640px;max-width:640px;background:#ffffff;border:1px solid #F3F6FA;border-radius:12px;overflow:hidden;">
            <tr>
              <td style="background:#0B1F3A;padding:24px 28px;color:#ffffff;">
                <table role="presentation" width="100%" cellspacing="0" cellpadding="0">
                  <tr>
                    <td valign="middle">
                      <img src="https://levinnovation.portal.agentyx.one/api/public/templates/email/logo?tenant=levinnovation" alt="LEV Innovation" width="40" height="40" style="display:block;border:0;border-radius:6px;background:#ffffff;padding:4px;" />
                    </td>
                    <td valign="middle" style="padding-left:12px;font-size:20px;font-weight:700;line-height:1.2;">LEV Innovation</td>
                  </tr>
                </table>
              </td>
            </tr>
            <tr>
              <td style="padding:28px;">{{body_html}}</td>
            </tr>
            <tr>
              <td style="padding:18px 28px;background:#F3F6FA;font-size:12px;line-height:1.6;color:#555;">
                <div>Equipo LEV Innovation</div>
                <div style="margin-top:6px;">LEV Innovation · {{year}}</div>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>';

const rendered = template
  .replace('{{body_html}}', bodyContent)
  .replace('{{subject}}', data.subject || '')
  .replace('{{year}}', String(new Date().getFullYear()));

return [{
  json: {
    to: data.to || '',
    from: 'noreply@levinnovation.com',
    subject: data.subject || '',
    html: rendered,
    cc: data.cc || []
  }
}];
